{
 "summary": "Working notes: Order-events consumer backlog.",
 "claims": [
  {
   "claim": "The order-events dead-letter topic received 3,916 messages during the backlog.",
   "value": "3,916",
   "source": "third_party",
   "via": "Tobias Fennimore's postmortem draft \"Order events backlog\"",
   "verified": "no"
  },
  {
   "claim": "Disk usage on the fullest Kafka broker reached 91.4% (broker id 6, mount /var/lib/kafka, host kfk-east-b).",
   "value": "91.4%",
   "source": "third_party",
   "via": "Agnes Kowalczyk's Confluence page \"Kafka capacity and config\"",
   "verified": "no"
  },
  {
   "claim": "The on-call engineer for orders changes every Monday.",
   "value": "",
   "source": "user",
   "via": "user message",
   "verified": "no"
  },
  {
   "claim": "No broker in the prod-east cluster restarted during the night.",
   "value": "",
   "source": "observed",
   "via": "`kubectl get pods -n kafka` output",
   "verified": "yes"
  },
  {
   "claim": "The consumer lag alert first fired at 23:47 UTC.",
   "value": "23:47 UTC",
   "source": "user",
   "via": "user message",
   "verified": "no"
  },
  {
   "claim": "The backlog took 3 hours 41 minutes to drain once consumers recovered (consumer group fulfil-svc, topic order-events, cluster prod-east).",
   "value": "3 hours 41 minutes",
   "source": "observed",
   "via": "Prometheus range result for the consumer lag metric",
   "verified": "yes"
  },
  {
   "claim": "The fulfil-svc service is owned by Radek Ilunga.",
   "value": "Radek Ilunga",
   "source": "observed",
   "via": "service catalog API response for fulfil-svc",
   "verified": "yes"
  },
  {
   "claim": "The fulfil-svc consumers run in the orders-prod namespace.",
   "value": "",
   "source": "observed",
   "via": "`kubectl get deploy -n orders-prod` output",
   "verified": "yes"
  },
  {
   "claim": "The fulfil-svc max.poll.interval.ms setting was last changed on 2026-09-28 (repo orders-config, file kafka/fulfil-svc.yaml, commit e5c1f0b).",
   "value": "2026-09-28",
   "source": "own_guess",
   "via": "none (my own assumption)",
   "verified": "no"
  },
  {
   "claim": "The order-events topic uses the cluster's default replication settings.",
   "value": "",
   "source": "observed",
   "via": "`kafka-topics --describe --topic order-events` output",
   "verified": "yes"
  },
  {
   "claim": "Consumer lag on the order-events topic peaked at 1,286,409 messages.",
   "value": "1,286,409",
   "source": "own_guess",
   "via": "none (my own assumption)",
   "verified": "no"
  },
  {
   "claim": "Inventory lookups from fulfil-svc go through an internal HTTP API.",
   "value": "",
   "source": "user",
   "via": "user message",
   "verified": "no"
  },
  {
   "claim": "Shipping updates go out through a separate notifier service.",
   "value": "",
   "source": "user",
   "via": "user message",
   "verified": "no"
  },
  {
   "claim": "The fulfil-svc release deployed when the backlog began was v4.12.7 (deployment fulfil-svc, namespace orders-prod, label app.kubernetes.io/version).",
   "value": "v4.12.7",
   "source": "user",
   "via": "user message",
   "verified": "no"
  }
 ]
}

